// API Route: GET /api/reports/positions
// Serves position reports generated by positionReport.ts (migrated from RPTPOS00.cbl)

import { NextResponse } from "next/server";
import { withErrorHandler, AppError } from "@/lib/errorHandler";
import {
  generatePositionReport,
  positionReportToCsv,
} from "@/services/reporting/positionReport";
import type { ApiResponse, PositionReport } from "@/types";

export const GET = withErrorHandler(async (request: Request) => {
  const start = Date.now();
  const { searchParams } = new URL(request.url);

  const dateParam = searchParams.get("date");
  const portfolioId = searchParams.get("portfolioId");
  const format = searchParams.get("format") ?? "json";

  if (format !== "json" && format !== "csv") {
    throw new AppError({
      message: "Invalid format parameter. Use 'json' or 'csv'.",
      httpStatus: 400,
      severity: 1,
      errorCode: "BADFMT",
    });
  }

  const date = dateParam ? new Date(dateParam) : undefined;
  if (dateParam && isNaN(date!.getTime())) {
    throw new AppError({
      message: "Invalid date parameter. Use ISO 8601 format (YYYY-MM-DD).",
      httpStatus: 400,
      severity: 1,
      errorCode: "BADDATE",
    });
  }

  const report = await generatePositionReport({
    date,
    portfolioId: portfolioId ?? undefined,
    format: format as "json" | "csv",
  });

  if (format === "csv") {
    const csv = positionReportToCsv(report);
    return new NextResponse(csv, {
      status: 200,
      headers: {
        "Content-Type": "text/csv",
        "Content-Disposition": `attachment; filename="position-report-${report.reportDate}.csv"`,
      },
    });
  }

  const response: ApiResponse<PositionReport> = {
    success: true,
    data: report,
    metadata: {
      generatedAt: new Date().toISOString(),
      processingTimeMs: Date.now() - start,
    },
  };

  return NextResponse.json(response);
});
